import{_ as a,H as t,f as o,i as p}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"结束语-站在聚光灯下","description":"","frontmatter":{},"headers":[{"level":2,"title":"发现自己的兴趣","slug":"发现自己的兴趣","link":"#发现自己的兴趣","children":[]},{"level":2,"title":"创造机会让自己成长","slug":"创造机会让自己成长","link":"#创造机会让自己成长","children":[]},{"level":2,"title":"走到聚光灯下","slug":"走到聚光灯下","link":"#走到聚光灯下","children":[]},{"level":2,"title":"Say Goodbye","slug":"say-goodbye","link":"#say-goodbye","children":[]}],"relativePath":"SpringCloud微服务项目实战/结束语-站在聚光灯下.md","filePath":"SpringCloud微服务项目实战/结束语-站在聚光灯下.md","lastUpdated":1795535212000}'),i={name:"SpringCloud微服务项目实战/结束语-站在聚光灯下.md"};function l(n,e,r,s,d,h){return t(),o("div",null,[...e[0]||(e[0]=[p('<h1 id="结束语-站在聚光灯下" tabindex="-1">结束语-站在聚光灯下 <a class="header-anchor" href="#结束语-站在聚光灯下" aria-label="Permalink to &quot;结束语-站在聚光灯下&quot;">​</a></h1><p>逝者如斯夫，不舍昼夜。写专栏的这段时间，我时常感叹晚上时间不够用。每天晚上我都要经历激烈的思想斗争，决定今晚是相聚王者峡谷，还是写极客专栏。实在抵不过团队小伙伴的热情相邀，所以每次思想斗争的结果都惊人地相似，除了周末 8 点到 9 点的时候，我每晚都要和团队小伙伴们去丈量王者峡谷的每一寸土地。</p><p>这让我想明白了一个道理，好学生和差学生混在一块，通常是差学生带着好学生一块玩，就没见过哪个好学生领着差学生一块写作业的。所以，圈子很重要，你所在的圈子决定了你的成就，优秀的圈子是能推着你不断前进的。你要尽量突破自己圈子的上限，平时多和王者组团征战峡谷，不要带白银和青铜上分了。</p><p>走走停停，想哪说哪了罢。</p><h2 id="发现自己的兴趣" tabindex="-1">发现自己的兴趣 <a class="header-anchor" href="#发现自己的兴趣" aria-label="Permalink to &quot;发现自己的兴趣&quot;">​</a></h2><p>爱因斯坦是这样解释相对论的，他说如果和你爱的人在一起，你会感觉一小时就像一分钟一样快，而如果你和一个讨厌的人呆在一起，你会发现即使一刻钟也像一个世纪那么漫长。我深有同感，我打王者的时候眼睛一闭一睁这一小时就过去了，而写极客专栏的时候一小时就像过了一辈子那么长。</p><p>兴趣，还真是一个催人奋进的东西。</p><p>我共事过的同事中，有一位架构师，叫他 Z 君好了。Z 是一位为代码而生的人，他的专业是生物，过腻了日复一日给小白鼠扎针的日子，跳到 IT 圈子里当了卷王。</p><p>Z 君闲暇时刻最喜欢做的事情，是回到阳澄湖的家里，坐在后院一边晒太阳一边敲代码。碰上团队组织的娱乐活动，我在一旁逗女同事，他坐旁边写代码；中午吃完饭我带女同事去园区日常遛弯，他回到办公室还是写代码。说 Z 君是在用生命研究技术，一点也不为过，这就极了阿里的程序员之神多隆，只不过没他有钱而已。</p><p>当年和 Z 争论架构设计的场景令我印象深刻，他会带着自己的代码原型和大量的实践细节，给出适合业务的方案。在如今这个 PPT 架构师横行的社会，架构师们浮于纸上谈兵，很少有人可以像 Z 一样真正深入技术细节沉下心来思考。所以我一直有这么一个认知，不写代码的一线架构师，早以失去了对业务和技术的敏感，十有八九是水货。</p><p>我经常拿自己和 Z 对比，我在专业技术领域上无法达到他一样的高度，归根结底是自己对技术不够热爱。我并不喜欢编程，相比较撕逼扯皮来说，我更喜欢和人打交道的事情。编程于我而言，就像渔夫打渔，厨师烧菜，只是一种维持生计的手段。脱离了兴趣，并不妨碍我在这个领域成为优秀的专家，但却很难成为顶尖的那一拨人。</p><p>天赋和努力很重要，兴趣也一样重要，找到自己真正感兴趣的技术方向，感兴趣的业务，你的上限可能会更高。</p><h2 id="创造机会让自己成长" tabindex="-1">创造机会让自己成长 <a class="header-anchor" href="#创造机会让自己成长" aria-label="Permalink to &quot;创造机会让自己成长&quot;">​</a></h2><p>我刚毕业的时候入职了一家外企，办公语言是英文，平时开会和发邮件也要用英文。彼时我的英文虽然不能说烂，但口语听力早已是年久失修，一碰到和外国人开会那就像参加综艺节目一样，我来比划他来猜。</p><p>入职第一周的某一天，老板到我位子上给我分了一个任务：“Vincent 啊，你去 schedule 一个meeting，make sure 把这个 project 的 stakeholder 全都 involve 进来”。后来老板说了什么我一点都记不起来，我感觉整个人像喝了假酒一样懵逼。我心想这下完犊子了，我连中国人说话我都听不懂，以后工作可怎么办？</p><p>很长一段时间以来，我只能靠提前写好的英文小抄来应付每天的例会，偶尔被问到听不懂的问题还会采用拔网线的方式避免尴尬。这个问题困扰了我蛮久，靠每天开几场会是不能有效提高英文听说能力的，我需要创造更多的和老外交流的机会。</p><p>再后来，在和外国同事沟通项目或者问题的时候，我但凡能开会讨论的就绝不回邮件，彻底拉下脸来创造一切可以交流的机会。考虑到时差关系，我经常早上六七点钟或者晚上 11 点以后到线上找同事尬聊，从一开始只聊工作上的项目，后来逐渐地可以聊些生活琐事，再到后来就能一起吐槽万恶的美帝资本主义了。</p><p>十多年过去了，当我回想自己职业经历的时候，我发现自己成长最快的几个阶段，都是靠着这种主动创造机会的方式，自我驱动达成的。</p><p>在面试的时候，我特别喜欢考察候选人的自我驱动能力，虽然这种能力不能保证你一定会成为一个成功的人，但它能保证当机会到来的时候，你有勇气去挑战自己，当面临困难的时候，你也有勇气去做出改变。</p><h2 id="走到聚光灯下" tabindex="-1">走到聚光灯下 <a class="header-anchor" href="#走到聚光灯下" aria-label="Permalink to &quot;走到聚光灯下&quot;">​</a></h2><p>Linus Torvalds 有一句被程序员奉为圣经的名言：Talk is cheap, show me the code。</p><p>而我想告诉你的是，这句话连一个标点符号都不要信。Talk 之所以 cheap，是因为这句话是Linus 说的，一位成名已久，站在神坛顶端的男人。</p><p>历史是任人打扮的小姑娘，总是由胜利者书写。似乎当你足够成功的时候，说出去的每一句话都会变得极富哲理，引来无数人顶礼膜拜。</p><p>比如鲁迅先生在《秋夜》中写到：“我家门前有两棵树，一棵是枣树，另一颗还是枣树”。我已经记不清有多少次，这句话出现在语文试卷中，我也曾写下各种标准答案，描述作者想要表达的情感和意境。直到后来，我也写了一篇和秋有关的作文，其中第一句是这样的：“我家阳台有两盆花，一盆是菊花，另一盆还是菊花”，那次我被当做全班的反面教材，站到讲台上描述着自己的心理阴影面积。</p><p>同样的话，有的人说出来就是圣经，有的人说出来就是歪嘴和尚念歪经。</p><p>我们不得不承认自己大概率不是 Linus 一样的天才，而且确实也很难取得他一样的成绩。两耳不闻窗外事，一心只 show me the code，对大部分普通人来说，是一条非常陡峭的职业发展路径。如何让你做的事情被更多的人看到，如何扩大自己的影响力，如何通过向上管理让老板知道你所创造的价值，这些很难通过 code review 来体现。</p><p>所以，从幕后，走到聚光灯下吧。怎么做？听听自个儿心里的答案吧。</p><h2 id="say-goodbye" tabindex="-1">Say Goodbye <a class="header-anchor" href="#say-goodbye" aria-label="Permalink to &quot;Say Goodbye&quot;">​</a></h2><p>一根烟的功夫，听我讲了几个小故事，传达的价值观正确又或者不正确，who cares。但终有一日，你也将会离开这个行业，是光荣退休还是中年失业，是平步青云还是无奈转行，whoknows。</p><p>是谁都无法阻挡，阻挡时间改变，就说再见说再见。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD-%25E7%25AB%2599%25E5%259C%25A8%25E8%2581%259A%25E5%2585%2589%25E7%2581%25AF%25E4%25B8%258B/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD-%25E7%25AB%2599%25E5%259C%25A8%25E8%2581%259A%25E5%2585%2589%25E7%2581%25AF%25E4%25B8%258B/1.png" alt=""></a></p>',31)])])}const u=a(i,[["render",l]]);export{c as __pageData,u as default};
